# @param {"type": "dropdown", "options": ["All", "Laptop", "Phone", "Tablet", "Headphones", "Monitor"], "default": "All"}
product_filter = "All"

if product_filter == "All":
    filtered = df
else:
    filtered = df[df['product'] == product_filter]

print(f"Product: {product_filter} — {len(filtered)} orders")
plot_bar(filtered.groupby('region')['revenue'].sum().reset_index(), x='region', y='revenue', title=f'{product_filter} Revenue by Region')

# @param {"type": "number", "min": 0, "max": 5000, "step": 100, "default": 1000}
min_revenue = 1000
# @param {"type": "checkbox", "default": true}
show_chart = True
high_value = df[df['revenue'] >= min_revenue]
print(f"Orders with revenue >= ${min_revenue}: {len(high_value)} ({len(high_value)/len(df)*100:.1f}%)")
if show_chart:
    display(plot_histogram(high_value, 'revenue', bins=20, title=f'Revenue Distribution (>= ${min_revenue})'))
else:
    display(high_value.head(10))

# @param {"type": "text", "default": "revenue", "placeholder": "column name"}
column_name = "revenue"

if column_name in df.columns:
    print(f"Stats for '{column_name}':")
    print(f"  Mean: {df[column_name].mean():.2f}")
    print(f"  Median: {df[column_name].median():.2f}")
    print(f"  Std: {df[column_name].std():.2f}")
    plot_histogram(df, column_name, title=f'Distribution of {column_name}')
else:
    print(f"Column '{column_name}' not found. Available: {list(df.columns)}")

# @param {"type": "dropdown", "options": ["revenue", "quantity", "unit_price"], "default": "revenue"}
metric = "revenue"

# @param {"type": "slider", "min": 3, "max": 20, "step": 1, "default": 5}
top_n = 5

# @param {"type": "dropdown", "options": ["product", "region"], "default": "product"}
group_by = "product"

result = df.groupby(group_by)[metric].sum().nlargest(top_n).reset_index()
print(f"Top {top_n} {group_by}s by {metric}:")
plot_bar(result, x=group_by, y=metric, title=f'Top {top_n} {group_by}s by {metric}')
